const query = $input.item.json.query || {};
if (query['hub.verify_token'] === 'CLIXA_SECRET_TOKEN_2026') {
  return [{ json: { text: query['hub.challenge'] } }];
}
return [{ json: { text: 'Forbidden' } }];

const body = $input.item.json.body || $input.item.json;
let from = '';
let messageText = '';
let senderName = '';

if (body.senderData && body.messageData) {
  from = body.senderData.chatId;
  senderName = body.senderData.senderName || '';
  messageText = body.messageData.textMessageData?.textMessage || body.messageData.extendedTextMessageData?.text || '';
} else if (body.entry && body.entry[0]?.changes[0]?.value?.messages) {
  const msg = body.entry[0].changes[0].value.messages[0];
  from = msg.from;
  messageText = msg.text?.body || '';
}

if (!messageText || body.typeWebhook === 'outgoingMessageReceived') {
  return [];
}

return [{
  json: {
    from,
    senderName,
    messageText,
    sessionId: from || 'default_session',
    adminPhone: '212661344054@c.us'
  }
}];
